#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Passo 9 - Foreground Service + notificacao com 5 controles (Player3D)

O que este script faz:
1. Cria app/src/main/java/com/android/gallery3d/app/MusicPlaybackService.java
   (novo arquivo - Service que passa a ser o dono do MediaPlayer, com
   MediaSession e notificacao MediaStyle com 5 botoes: Repetir todas,
   Anterior, Play/Pause, Proxima, Repetir uma).
2. Adiciona as strings usadas pelo Service em res/values/strings.xml.
3. Registra o <service> no AndroidManifest.xml (foregroundServiceType
   "mediaPlayback", exported=false).
4. Cria os 4 icones que faltavam em drawable-nodpi/: previous, next,
   repeat_all, repeat_one (mesmo estilo/paleta do ic_vidcontrol_play/pause
   ja existentes).

IMPORTANTE: este passo NAO liga o MoviePlayer.java a este Service - essa
conexao (item 9.3 da especificacao) e feita no Passo 4, porque e nesse
passo que MoviePlayer.java deixa de usar VideoView. O Service criado aqui
ja fica completo e funcional por conta propria, pronto pra ser consumido
no Passo 4 via bindService().

Rode este script na RAIZ do projeto (~/Galeria3D no Termux):
    python3 passo9_service_notificacao.py

Regras seguidas (workflow combinado):
- Falha cedo se pre-requisitos (Passo 1/2/3) nao estiverem no estado
  esperado, sem tocar em nada.
- Faz backup de cada arquivo existente que for editado (.bak_passo9).
- So aplica cada substituicao se ela bater EXATAMENTE 1 vez; caso
  contrario, para e mostra o erro sem tocar no arquivo.
- E idempotente: rodar de novo depois de aplicado nao duplica nem corrompe
  nada, so avisa o que ja existe.
- Termina com verificacao (grep + checagem de recursos referenciados).
"""

import base64
import os
import sys

MUSIC_SERVICE_JAVA = "/*\n * Passo 9 - Foreground Service + notificacao com 5 controles.\n *\n * Nao existia nenhum Service/MediaSession/NotificationChannel de midia no\n * projeto antes deste arquivo (confirmado por busca no codigo). Criado do\n * zero seguindo a especificacao do Passo 9 do Player3D_contexto.md.\n *\n * Este Service passa a ser o unico dono do MediaPlayer da reproducao de\n * audio. A tela de reproducao (MoviePlayer.java, adaptada no Passo 4) vira\n * cliente deste Service via bindService()/Binder - essa conexao (item 9.3\n * da especificacao) e feita no Passo 4, nao aqui, porque MoviePlayer.java\n * ainda usa VideoView e so sera reescrito nesse passo seguinte. O Service\n * abaixo ja fica completo e funcional por conta propria (9.1 + 9.2).\n */\npackage com.android.gallery3d.app;\n\nimport android.app.Notification;\nimport android.app.NotificationChannel;\nimport android.app.NotificationManager;\nimport android.app.PendingIntent;\nimport android.app.Service;\nimport android.content.Context;\nimport android.content.Intent;\nimport android.graphics.Bitmap;\nimport android.media.AudioAttributes;\nimport android.media.AudioManager;\nimport android.media.MediaPlayer;\nimport android.media.session.MediaSession;\nimport android.media.session.PlaybackState;\nimport android.net.Uri;\nimport android.os.Binder;\nimport android.os.Build;\nimport android.os.IBinder;\nimport android.util.Log;\n\nimport com.android.gallery3d.R;\n\nimport java.io.IOException;\n\npublic class MusicPlaybackService extends Service\n        implements MediaPlayer.OnPreparedListener, MediaPlayer.OnCompletionListener,\n        MediaPlayer.OnErrorListener {\n\n    private static final String TAG = \"MusicPlaybackService\";\n\n    private static final String CHANNEL_ID = \"player3d_playback_channel\";\n    private static final int NOTIFICATION_ID = 1;\n\n    public static final String ACTION_PLAY_PAUSE =\n            \"com.android.gallery3d.app.action.PLAY_PAUSE\";\n    public static final String ACTION_NEXT =\n            \"com.android.gallery3d.app.action.NEXT\";\n    public static final String ACTION_PREVIOUS =\n            \"com.android.gallery3d.app.action.PREVIOUS\";\n    public static final String ACTION_TOGGLE_REPEAT_ALL =\n            \"com.android.gallery3d.app.action.TOGGLE_REPEAT_ALL\";\n    public static final String ACTION_TOGGLE_REPEAT_ONE =\n            \"com.android.gallery3d.app.action.TOGGLE_REPEAT_ONE\";\n    public static final String ACTION_STOP =\n            \"com.android.gallery3d.app.action.STOP\";\n\n    // Volta ao inicio da faixa em vez de ir pra anterior de fato quando o\n    // usuario ja passou desse tanto de tempo tocando (mesmo valor usado no\n    // botao \"Faixa anterior\" da tela de reproducao, Passo 4.2).\n    private static final int PREVIOUS_RESTART_THRESHOLD_MS = 3000;\n\n    public enum RepeatMode { OFF, ALL, ONE }\n\n    /**\n     * Implementado por quem estiver de fato tocando as faixas (MoviePlayer,\n     * a partir do Passo 4) para reagir a mudancas de estado de reproducao,\n     * refletindo na UI da tela de reproducao.\n     */\n    public interface Callback {\n        void onPlaybackStateChanged(boolean isPlaying);\n        void onRepeatModeChanged(RepeatMode mode);\n        void onTrackError(Exception error);\n    }\n\n    /**\n     * Implementado por quem tem a lista/album atual (MoviePlayer, a partir\n     * do Passo 4) para o Service saber qual e a proxima/anterior faixa\n     * quando o pedido vem da notificacao, da tela de bloqueio, ou dos\n     * botoes da propria tela de reproducao - e a mesma fonte de verdade\n     * descrita no item 9.3 da especificacao.\n     */\n    public interface QueueController {\n        void onNextRequested();\n        void onPreviousRequested();\n    }\n\n    private final IBinder mBinder = new LocalBinder();\n\n    public class LocalBinder extends Binder {\n        public MusicPlaybackService getService() {\n            return MusicPlaybackService.this;\n        }\n    }\n\n    private MediaPlayer mMediaPlayer;\n    private MediaSession mMediaSession;\n    private NotificationManager mNotificationManager;\n\n    private Callback mCallback;\n    private QueueController mQueueController;\n\n    private Uri mCurrentUri;\n    private String mCurrentTitle = \"\";\n    private String mCurrentArtist = \"\";\n    private Bitmap mCurrentCover;\n\n    private RepeatMode mRepeatMode = RepeatMode.OFF;\n    private boolean mPreparing = false;\n\n    @Override\n    public void onCreate() {\n        super.onCreate();\n        createNotificationChannel();\n\n        mMediaSession = new MediaSession(this, TAG);\n        mMediaSession.setCallback(new MediaSession.Callback() {\n            @Override\n            public void onPlay() {\n                resume();\n            }\n\n            @Override\n            public void onPause() {\n                pause();\n            }\n\n            @Override\n            public void onSkipToNext() {\n                requestNext();\n            }\n\n            @Override\n            public void onSkipToPrevious() {\n                requestPrevious();\n            }\n\n            @Override\n            public void onCustomAction(String action, android.os.Bundle extras) {\n                handleAction(action);\n            }\n        });\n        mMediaSession.setActive(true);\n    }\n\n    @Override\n    public int onStartCommand(Intent intent, int flags, int startId) {\n        if (intent != null && intent.getAction() != null) {\n            handleAction(intent.getAction());\n        }\n        return START_NOT_STICKY;\n    }\n\n    @Override\n    public IBinder onBind(Intent intent) {\n        return mBinder;\n    }\n\n    private void handleAction(String action) {\n        if (action == null) return;\n        switch (action) {\n            case ACTION_PLAY_PAUSE:\n                togglePlayPause();\n                break;\n            case ACTION_NEXT:\n                requestNext();\n                break;\n            case ACTION_PREVIOUS:\n                requestPrevious();\n                break;\n            case ACTION_TOGGLE_REPEAT_ALL:\n                toggleRepeatAll();\n                break;\n            case ACTION_TOGGLE_REPEAT_ONE:\n                toggleRepeatOne();\n                break;\n            case ACTION_STOP:\n                stopPlaybackAndService();\n                break;\n            default:\n                break;\n        }\n    }\n\n    // ---------------------------------------------------------------------\n    // API publica usada pelo cliente ligado via bindService() (MoviePlayer,\n    // Passo 4) e pelos PendingIntents da notificacao/MediaSession.\n    // ---------------------------------------------------------------------\n\n    public void setCallback(Callback callback) {\n        mCallback = callback;\n    }\n\n    public void setQueueController(QueueController controller) {\n        mQueueController = controller;\n    }\n\n    /** Comeca a tocar uma nova faixa (chamado pelo cliente ao trocar de item). */\n    public void playTrack(Uri uri, String title, String artist, Bitmap cover) {\n        mCurrentUri = uri;\n        mCurrentTitle = title != null ? title : \"\";\n        mCurrentArtist = artist != null ? artist : \"\";\n        mCurrentCover = cover;\n\n        releaseMediaPlayer();\n        mMediaPlayer = new MediaPlayer();\n        mMediaPlayer.setAudioAttributes(new AudioAttributes.Builder()\n                .setUsage(AudioAttributes.USAGE_MEDIA)\n                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)\n                .build());\n        mMediaPlayer.setOnPreparedListener(this);\n        mMediaPlayer.setOnCompletionListener(this);\n        mMediaPlayer.setOnErrorListener(this);\n        mPreparing = true;\n        try {\n            mMediaPlayer.setDataSource(getApplicationContext(), uri);\n            mMediaPlayer.prepareAsync();\n        } catch (IOException | IllegalStateException e) {\n            Log.e(TAG, \"Falha ao preparar a faixa: \" + uri, e);\n            mPreparing = false;\n            if (mCallback != null) mCallback.onTrackError(e);\n            return;\n        }\n\n        // Precisa entrar em foreground em ate 5s do inicio da reproducao\n        // (exigencia do Android 12+ para foregroundServiceType=\"mediaPlayback\"),\n        // entao chamamos ja, com uma notificacao \"preparando\" - ela e\n        // atualizada de novo assim que o MediaPlayer estiver pronto.\n        startForeground(NOTIFICATION_ID, buildNotification());\n    }\n\n    @Override\n    public void onPrepared(MediaPlayer mp) {\n        mPreparing = false;\n        mp.start();\n        updatePlaybackState();\n        notifyState(true);\n    }\n\n    @Override\n    public void onCompletion(MediaPlayer mp) {\n        if (mRepeatMode == RepeatMode.ONE) {\n            mp.seekTo(0);\n            mp.start();\n            updatePlaybackState();\n            notifyState(true);\n            return;\n        }\n        // Repetir todas ou tocar a proxima faixa da fila e decisao de quem\n        // controla a fila (MoviePlayer) - o Service so avisa que acabou.\n        requestNext();\n    }\n\n    @Override\n    public boolean onError(MediaPlayer mp, int what, int extra) {\n        mPreparing = false;\n        Log.e(TAG, \"MediaPlayer error: what=\" + what + \" extra=\" + extra);\n        if (mCallback != null) {\n            mCallback.onTrackError(new IOException(\"MediaPlayer error \" + what + \"/\" + extra));\n        }\n        return true;\n    }\n\n    public void togglePlayPause() {\n        if (mMediaPlayer == null || mPreparing) return;\n        if (mMediaPlayer.isPlaying()) {\n            pause();\n        } else {\n            resume();\n        }\n    }\n\n    public void pause() {\n        if (mMediaPlayer != null && !mPreparing && mMediaPlayer.isPlaying()) {\n            mMediaPlayer.pause();\n            updatePlaybackState();\n            notifyState(false);\n        }\n    }\n\n    public void resume() {\n        if (mMediaPlayer != null && !mPreparing && !mMediaPlayer.isPlaying()) {\n            mMediaPlayer.start();\n            updatePlaybackState();\n            notifyState(true);\n        }\n    }\n\n    public void seekTo(int milliseconds) {\n        if (mMediaPlayer != null && !mPreparing) {\n            mMediaPlayer.seekTo(milliseconds);\n            updatePlaybackState();\n        }\n    }\n\n    public int getCurrentPosition() {\n        return (mMediaPlayer != null && !mPreparing) ? mMediaPlayer.getCurrentPosition() : 0;\n    }\n\n    public int getDuration() {\n        return (mMediaPlayer != null && !mPreparing) ? mMediaPlayer.getDuration() : 0;\n    }\n\n    public boolean isPlaying() {\n        return mMediaPlayer != null && !mPreparing && mMediaPlayer.isPlaying();\n    }\n\n    public RepeatMode getRepeatMode() {\n        return mRepeatMode;\n    }\n\n    public void toggleRepeatAll() {\n        mRepeatMode = (mRepeatMode == RepeatMode.ALL) ? RepeatMode.OFF : RepeatMode.ALL;\n        if (mCallback != null) mCallback.onRepeatModeChanged(mRepeatMode);\n        updateNotification();\n    }\n\n    public void toggleRepeatOne() {\n        mRepeatMode = (mRepeatMode == RepeatMode.ONE) ? RepeatMode.OFF : RepeatMode.ONE;\n        if (mCallback != null) mCallback.onRepeatModeChanged(mRepeatMode);\n        updateNotification();\n    }\n\n    /**\n     * Clique curto/duplo de \"faixa anterior\": se ja passou de 3s tocando a\n     * faixa atual, volta pro inicio dela; senao, pede a faixa anterior de\n     * verdade pra quem controla a fila.\n     */\n    private void requestPrevious() {\n        if (mMediaPlayer != null && !mPreparing && mMediaPlayer.getCurrentPosition() > PREVIOUS_RESTART_THRESHOLD_MS) {\n            seekTo(0);\n            return;\n        }\n        if (mQueueController != null) {\n            mQueueController.onPreviousRequested();\n        }\n    }\n\n    private void requestNext() {\n        if (mQueueController != null) {\n            mQueueController.onNextRequested();\n        }\n    }\n\n    private void stopPlaybackAndService() {\n        releaseMediaPlayer();\n        stopForeground(true);\n        stopSelf();\n    }\n\n    @Override\n    public void onDestroy() {\n        releaseMediaPlayer();\n        if (mMediaSession != null) {\n            mMediaSession.setActive(false);\n            mMediaSession.release();\n        }\n        super.onDestroy();\n    }\n\n    private void releaseMediaPlayer() {\n        if (mMediaPlayer != null) {\n            try {\n                mMediaPlayer.reset();\n                mMediaPlayer.release();\n            } catch (IllegalStateException e) {\n                Log.w(TAG, \"Erro ao liberar MediaPlayer\", e);\n            }\n            mMediaPlayer = null;\n        }\n        mPreparing = false;\n    }\n\n    private void notifyState(boolean isPlaying) {\n        if (mCallback != null) mCallback.onPlaybackStateChanged(isPlaying);\n        updateNotification();\n    }\n\n    private void updatePlaybackState() {\n        long actions = PlaybackState.ACTION_PLAY_PAUSE\n                | PlaybackState.ACTION_PLAY\n                | PlaybackState.ACTION_PAUSE\n                | PlaybackState.ACTION_SKIP_TO_NEXT\n                | PlaybackState.ACTION_SKIP_TO_PREVIOUS\n                | PlaybackState.ACTION_SEEK_TO;\n\n        int state = isPlaying() ? PlaybackState.STATE_PLAYING : PlaybackState.STATE_PAUSED;\n\n        PlaybackState.Builder builder = new PlaybackState.Builder()\n                .setActions(actions)\n                .setState(state, getCurrentPosition(), 1.0f)\n                .addCustomAction(ACTION_TOGGLE_REPEAT_ALL,\n                        getString(R.string.player3d_repeat_all),\n                        R.drawable.ic_vidcontrol_repeat_all)\n                .addCustomAction(ACTION_TOGGLE_REPEAT_ONE,\n                        getString(R.string.player3d_repeat_one),\n                        R.drawable.ic_vidcontrol_repeat_one);\n\n        mMediaSession.setPlaybackState(builder.build());\n\n        android.media.MediaMetadata.Builder metadata = new android.media.MediaMetadata.Builder()\n                .putString(android.media.MediaMetadata.METADATA_KEY_TITLE, mCurrentTitle)\n                .putString(android.media.MediaMetadata.METADATA_KEY_ARTIST, mCurrentArtist)\n                .putLong(android.media.MediaMetadata.METADATA_KEY_DURATION, getDuration());\n        if (mCurrentCover != null) {\n            metadata.putBitmap(android.media.MediaMetadata.METADATA_KEY_ALBUM_ART, mCurrentCover);\n        }\n        mMediaSession.setMetadata(metadata.build());\n    }\n\n    // ---------------------------------------------------------------------\n    // Notificacao (5 botoes: Repetir todas - Anterior - Play/Pause -\n    // Proxima - Repetir uma), na mesma ordem da tela de reproducao (Passo\n    // 4.2): ALL e Anterior a direita do play/pause, Proxima e Repetir Uma a\n    // esquerda.\n    // ---------------------------------------------------------------------\n\n    private void createNotificationChannel() {\n        mNotificationManager = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n            NotificationChannel channel = new NotificationChannel(\n                    CHANNEL_ID,\n                    getString(R.string.player3d_notification_channel_name),\n                    NotificationManager.IMPORTANCE_LOW);\n            channel.setDescription(getString(R.string.player3d_notification_channel_description));\n            mNotificationManager.createNotificationChannel(channel);\n        }\n    }\n\n    private PendingIntent actionPendingIntent(String action) {\n        Intent intent = new Intent(this, MusicPlaybackService.class);\n        intent.setAction(action);\n        int flags = PendingIntent.FLAG_UPDATE_CURRENT;\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {\n            flags |= PendingIntent.FLAG_IMMUTABLE;\n        }\n        return PendingIntent.getService(this, action.hashCode(), intent, flags);\n    }\n\n    private Notification buildNotification() {\n        boolean playing = isPlaying();\n        // Nota: o estado visual \"ativado\" (ALL/1 destacado) dos botoes e\n        // especificado no Passo 4.2 para a tela de reproducao; a notificacao\n        // usa aqui o mesmo icone monocromatico nos dois estados.\n\n        Notification.Action repeatAll = new Notification.Action.Builder(\n                R.drawable.ic_vidcontrol_repeat_all,\n                getString(R.string.player3d_repeat_all),\n                actionPendingIntent(ACTION_TOGGLE_REPEAT_ALL)).build();\n\n        Notification.Action previous = new Notification.Action.Builder(\n                R.drawable.ic_vidcontrol_previous,\n                getString(R.string.player3d_previous),\n                actionPendingIntent(ACTION_PREVIOUS)).build();\n\n        Notification.Action playPause = new Notification.Action.Builder(\n                playing ? R.drawable.ic_vidcontrol_pause : R.drawable.ic_vidcontrol_play,\n                getString(playing ? R.string.player3d_pause : R.string.player3d_play),\n                actionPendingIntent(ACTION_PLAY_PAUSE)).build();\n\n        Notification.Action next = new Notification.Action.Builder(\n                R.drawable.ic_vidcontrol_next,\n                getString(R.string.player3d_next),\n                actionPendingIntent(ACTION_NEXT)).build();\n\n        Notification.Action repeatOne = new Notification.Action.Builder(\n                R.drawable.ic_vidcontrol_repeat_one,\n                getString(R.string.player3d_repeat_one),\n                actionPendingIntent(ACTION_TOGGLE_REPEAT_ONE)).build();\n\n        Notification.MediaStyle style = new Notification.MediaStyle()\n                .setMediaSession(mMediaSession.getSessionToken())\n                .setShowActionsInCompactView(1, 2, 3);\n\n        Notification.Builder builder = new Notification.Builder(this, CHANNEL_ID)\n                .setSmallIcon(R.drawable.ic_vidcontrol_play)\n                .setContentTitle(mCurrentTitle)\n                .setContentText(mCurrentArtist)\n                .setLargeIcon(mCurrentCover)\n                .setOngoing(playing)\n                .setOnlyAlertOnce(true)\n                .setStyle(style)\n                .addAction(repeatAll)\n                .addAction(previous)\n                .addAction(playPause)\n                .addAction(next)\n                .addAction(repeatOne);\n\n        return builder.build();\n    }\n\n    private void updateNotification() {\n        if (mNotificationManager == null) return;\n        mNotificationManager.notify(NOTIFICATION_ID, buildNotification());\n    }\n}\n"

ICONS_B64 = {
    "app/src/main/res/drawable-nodpi/ic_vidcontrol_previous.png": "",
    "app/src/main/res/drawable-nodpi/ic_vidcontrol_next.png": "",
    "app/src/main/res/drawable-nodpi/ic_vidcontrol_repeat_all.png": "",
    "app/src/main/res/drawable-nodpi/ic_vidcontrol_repeat_one.png": "",
}

SERVICE_JAVA_PATH = "app/src/main/java/com/android/gallery3d/app/MusicPlaybackService.java"
MANIFEST_PATH = "app/src/main/AndroidManifest.xml"
STRINGS_PATH = "app/src/main/res/values/strings.xml"
GALLERY_ACTIVITY = "app/src/main/java/com/android/gallery3d/app/GalleryActivity.java"

REQUIRED_FILES = [MANIFEST_PATH, STRINGS_PATH, GALLERY_ACTIVITY]


def fail(msg):
    print("ERRO: " + msg)
    sys.exit(1)


def check_prereqs():
    for f in REQUIRED_FILES:
        if not os.path.isfile(f):
            fail(
                "arquivo esperado nao encontrado: %s\n"
                "Rode este script na raiz do projeto (~/Galeria3D)." % f
            )
    ga = read(GALLERY_ACTIVITY)
    if "INCLUDE_LOCAL_VIDEO_ONLY" not in ga:
        fail(
            "GalleryActivity.java nao parece ter o Passo 2 aplicado "
            "(INCLUDE_LOCAL_VIDEO_ONLY nao encontrado). Rode o script do "
            "Passo 2 antes deste."
        )
    if os.path.isfile(SERVICE_JAVA_PATH):
        print("Aviso: %s ja existe - nao vou sobrescrever (idempotente)." % SERVICE_JAVA_PATH)


def read(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()


def write(path, content):
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(content)


def backup(path):
    bak = path + ".bak_passo9"
    if not os.path.isfile(bak):
        write(bak, read(path))
        print("Backup criado: %s" % bak)
    else:
        print("Backup ja existia, mantido: %s" % bak)


def replace_exactly_once(path, old, new, label):
    content = read(path)
    count = content.count(old)
    if count == 0:
        fail(
            "%s: trecho esperado nao encontrado em %s.\n"
            "Isso costuma significar que o Passo 9 ja foi aplicado, ou que "
            "o arquivo mudou desde a especificacao. Nada foi alterado."
            % (label, path)
        )
    if count > 1:
        fail(
            "%s: trecho apareceu %d vezes em %s (esperado exatamente 1). "
            "Nada foi alterado, script parou por seguranca."
            % (label, count, path)
        )
    content = content.replace(old, new, 1)
    write(path, content)
    print("OK: %s (%s)" % (label, path))


def create_service_java():
    if os.path.isfile(SERVICE_JAVA_PATH):
        return
    os.makedirs(os.path.dirname(SERVICE_JAVA_PATH), exist_ok=True)
    write(SERVICE_JAVA_PATH, MUSIC_SERVICE_JAVA)
    print("Criado: %s (%d bytes)" % (SERVICE_JAVA_PATH, len(MUSIC_SERVICE_JAVA)))


def create_icons():
    for path, b64 in ICONS_B64.items():
        if os.path.isfile(path):
            print("Aviso: %s ja existe, mantido." % path)
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        data = base64.b64decode(b64)
        with open(path, "wb") as fh:
            fh.write(data)
        print("Criado: %s (%d bytes)" % (path, len(data)))


def patch_strings():
    path = STRINGS_PATH
    if "player3d_notification_channel_name" in read(path):
        print("Aviso: strings do MusicPlaybackService ja existem em %s, mantidas." % path)
        return
    backup(path)
    old = (
        '    <!-- Activity label. This might show up in the activity-picker -->\n'
        '    <string name="movie_view_label">Video player</string>\n'
    )
    new = (
        '    <!-- Activity label. This might show up in the activity-picker -->\n'
        '    <string name="movie_view_label">Video player</string>\n'
        '    <!-- Passo 9: MusicPlaybackService - canal de notificacao e rotulos dos botoes -->\n'
        '    <string name="player3d_notification_channel_name">Reproducao de musica</string>\n'
        '    <string name="player3d_notification_channel_description">Controles de reproducao da faixa atual</string>\n'
        '    <string name="player3d_play">Tocar</string>\n'
        '    <string name="player3d_pause">Pausar</string>\n'
        '    <string name="player3d_previous">Faixa anterior</string>\n'
        '    <string name="player3d_next">Proxima faixa</string>\n'
        '    <string name="player3d_repeat_all">Repetir todas</string>\n'
        '    <string name="player3d_repeat_one">Repetir uma</string>\n'
    )
    replace_exactly_once(path, old, new, "strings do MusicPlaybackService")


def patch_manifest():
    path = MANIFEST_PATH
    backup(path)
    old = (
        '        <service android:name="com.android.camera.MediaSaveService" />\n'
        '    </application>'
    )
    new = (
        '        <service android:name="com.android.camera.MediaSaveService" />\n'
        '\n'
        '        <!-- Passo 9: Foreground Service da reproducao de audio -->\n'
        '        <service android:name="com.android.gallery3d.app.MusicPlaybackService"\n'
        '            android:foregroundServiceType="mediaPlayback"\n'
        '            android:exported="false" />\n'
        '    </application>'
    )
    replace_exactly_once(path, old, new, "<service> no AndroidManifest.xml")


def verify():
    print("\n--- Verificacao final ---")
    problems = []

    if not os.path.isfile(SERVICE_JAVA_PATH):
        problems.append("MusicPlaybackService.java nao foi criado")

    manifest = read(MANIFEST_PATH)
    if "MusicPlaybackService" not in manifest:
        problems.append("AndroidManifest.xml sem o <service> do MusicPlaybackService")
    if "foregroundServiceType=\"mediaPlayback\"" not in manifest:
        problems.append("AndroidManifest.xml sem foregroundServiceType=mediaPlayback")

    strings = read(STRINGS_PATH)
    for name in ["player3d_play", "player3d_pause", "player3d_previous",
                 "player3d_next", "player3d_repeat_all", "player3d_repeat_one",
                 "player3d_notification_channel_name"]:
        if ("name=\"%s\"" % name) not in strings:
            problems.append("strings.xml sem a string %s" % name)

    for path in ICONS_B64.keys():
        if not os.path.isfile(path):
            problems.append("icone nao encontrado: %s" % path)

    if problems:
        print("Encontrados problemas na verificacao final:")
        for p in problems:
            print("  - " + p)
        sys.exit(1)

    print("Tudo certo: nenhum resto do padrao antigo encontrado.")


def main():
    check_prereqs()
    create_service_java()
    create_icons()
    patch_strings()
    patch_manifest()
    verify()
